<?php
namespace App\Http\Controllers\API\Hub\V1;use App\Domain\ApiHub\Models\TenantApiOperationLink;use Illuminate\Http\Request;
final class TrackingController extends ApiV1Controller{public function show(Request$r,string$tracking){$link=TenantApiOperationLink::with('shipment.events')->where('tenant_id',$r->attributes->get('tenant')->id)->where('api_client_id',$r->attributes->get('api_client')->id)->whereHas('shipment',fn($q)=>$q->where('tracking_number',$tracking))->firstOrFail();$s=$link->shipment;$labels=['CREATED'=>'Creado','READY_FOR_PICKUP'=>'Listo para recolectar','PICKED_UP'=>'Recolectado','IN_TRANSIT'=>'En tránsito','OUT_FOR_DELIVERY'=>'En reparto','DELIVERY_FAILED'=>'No entregado','DELIVERED'=>'Entregado','CANCELED'=>'Cancelado'];return$this->ok($r,['tracking_number'=>$s->tracking_number,'current_status'=>$s->status,'human_status'=>$labels[$s->status]??'Actualización','timeline'=>$s->events->map(fn($e)=>['status'=>$e->status,'human_status'=>$labels[$e->status]??'Actualización','occurred_at'=>$e->occurred_at?->toIso8601String()])->all()]);}}
